package app.manga.manga;
import app.manga.common.UpstreamException;import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import java.net.URI;import java.time.Duration;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import java.util.concurrent.TimeUnit;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.client.SimpleClientHttpRequestFactory;import org.springframework.stereotype.Service;import org.springframework.web.client.HttpStatusCodeException;import org.springframework.web.client.RestClient;
@Service public class JikanProvider {
 private final RestClient client;private final ObjectMapper mapper;private final long ttl;private final long minGap;private volatile long lastCall=0;private final Map<String,Cache> cache=new ConcurrentHashMap<>();private record Cache(Object value,long expires){}
 public JikanProvider(@Value("${jikan.base-url}")String base,@Value("${jikan.connect-timeout-ms}")int connect,@Value("${jikan.read-timeout-ms}")int read,@Value("${jikan.cache-ttl-seconds}")long ttl,@Value("${jikan.max-requests-per-minute}")int rpm,ObjectMapper mapper){var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(Duration.ofMillis(connect));f.setReadTimeout(Duration.ofMillis(read));this.client=RestClient.builder().baseUrl(base).requestFactory(f).build();this.mapper=mapper;this.ttl=ttl*1000;this.minGap=Math.max(2000,60_000/Math.max(1,rpm));}
 public MangaDto.Page<List<MangaDto>> catalog(String q,String genre,String status,String type,String order,String sort,int page,int limit){var params=new LinkedHashMap<String,String>();if(q!=null&&!q.isBlank())params.put("q",q.trim());if(genre!=null&&!genre.isBlank())params.put("genres",genre);if(status!=null&&!status.isBlank())params.put("status",status);if(type!=null&&!type.isBlank())params.put("type",type);if(order!=null&&!order.isBlank())params.put("order_by",order);if(sort!=null&&!sort.isBlank())params.put("sort",sort);params.put("page",String.valueOf(page));params.put("limit",String.valueOf(limit));String key="catalog:"+params;JsonNode root=get("/manga",params,key);JsonNode pd=root.path("pagination");int current=pd.path("current_page").asInt(page);boolean next=pd.path("has_next_page").asBoolean(false);int total=pd.path("items").path("total").asInt(0);List<MangaDto> data=new ArrayList<>();root.path("data").forEach(n->data.add(map(n)));return new MangaDto.Page<>(data,new MangaDto.Pagination(current,limit,next,total));}
 public MangaDto detail(long id){return map(get("/manga/"+id,Map.of("-",""),"detail:"+id).path("data"));}
 public MangaDto.Page<List<MangaDto>> top(int page,int limit){JsonNode root=get("/top/manga",Map.of("page",String.valueOf(page),"limit",String.valueOf(limit)),"top:"+page+":"+limit);List<MangaDto> data=new ArrayList<>();root.path("data").forEach(n->data.add(map(n)));JsonNode p=root.path("pagination");return new MangaDto.Page<>(data,new MangaDto.Pagination(page,limit,p.path("has_next_page").asBoolean(),p.path("items").path("total").asInt()));}
 public List<MangaDto.GenreDto> genres(){JsonNode root=get("/genres/manga",Map.of(),"genres");List<MangaDto.GenreDto> out=new ArrayList<>();root.path("data").forEach(n->out.add(new MangaDto.GenreDto(n.path("mal_id").asInt(),text(n,"name"))));return out;}
 private JsonNode get(String path,Map<String,String> params,String key){Cache hit=cache.get(key);if(hit!=null&&hit.expires()>System.currentTimeMillis())return (JsonNode)hit.value();synchronized(this){long wait=minGap-(System.currentTimeMillis()-lastCall);if(wait>0)try{TimeUnit.MILLISECONDS.sleep(wait);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new UpstreamException(503,"UPSTREAM_UNAVAILABLE","Layanan metadata sementara tidak tersedia.");}lastCall=System.currentTimeMillis();}try{var uri=client.get().uri(b->{var u=b.path(path);params.forEach((k,v)->{if(!k.equals("-"))u.queryParam(k,v);});return u.build();}).retrieve().body(JsonNode.class);if(uri==null)throw new UpstreamException(503,"UPSTREAM_UNAVAILABLE","Layanan metadata memberikan respons kosong.");cache.put(key,new Cache(uri,System.currentTimeMillis()+ttl));return uri;}catch(HttpStatusCodeException e){int s=e.getStatusCode().value();if(s==404)throw new UpstreamException(404,"NOT_FOUND","Manga tidak ditemukan.");if((s==429||s>=500)&&hit!=null)return (JsonNode)hit.value();if(s==429)throw new UpstreamException(503,"UPSTREAM_RATE_LIMITED","Layanan metadata sedang membatasi permintaan. Coba lagi nanti.");throw new UpstreamException(503,"UPSTREAM_UNAVAILABLE","Layanan metadata sementara tidak tersedia.");}catch(UpstreamException e){throw e;}catch(Exception e){if(hit!=null)return (JsonNode)hit.value();throw new UpstreamException(503,"UPSTREAM_UNAVAILABLE","Tidak dapat terhubung ke layanan metadata.");}}
 static MangaDto map(JsonNode n){JsonNode images=n.path("images").path("jpg");String image=text(images,"large_image_url");if(image==null)image=text(images,"image_url");JsonNode titles=n.path("titles");String en=text(n,"title_english");if(en==null)en=firstTitle(titles,"English");String ja=text(n,"title_japanese");if(ja==null)ja=firstTitle(titles,"Japanese");List<String> authors=new ArrayList<>();n.path("authors").forEach(a->{String name=text(a,"name");if(name!=null)authors.add(name);});List<MangaDto.GenreDto> genres=new ArrayList<>();n.path("genres").forEach(g->{if(g.path("mal_id").canConvertToInt())genres.add(new MangaDto.GenreDto(g.path("mal_id").asInt(),text(g,"name")));});Integer chapters=n.path("chapters").isNumber()?n.path("chapters").asInt():null;Integer volumes=n.path("volumes").isNumber()?n.path("volumes").asInt():null;Double score=n.path("score").isNumber()?n.path("score").asDouble():null;if(score!=null&&score<=0)score=null;return new MangaDto(n.path("mal_id").asLong(),Objects.requireNonNullElse(text(n,"title"),"Untitled"),en,ja,image,text(n,"synopsis"),text(n,"type"),text(n,"status"),score,chapters,volumes,authors,genres,text(n,"url"));}
 static String text(JsonNode n,String key){JsonNode x=n.path(key);return x.isTextual()&&!x.asText().isBlank()?x.asText():null;}private static String firstTitle(JsonNode n,String type){for(JsonNode x:n)if(type.equalsIgnoreCase(text(x,"type")))return text(x,"title");return null;}
}
